W = 3
P = "Verbeterproject"

# ---------- MC ----------
mc("pp3-m01", W, P, "Welke twee succesfactoren noemt de les voor elke verandering?",
   ["Een ruim budget en een externe adviseur die de verandering begeleidt",
        "De uitvoerders betrekken en zichtbare steun van het management",
        "Een goed werkend FMIS en duidelijke KPI's op een dashboard",
        "Een strakke planning en een snelle big-bang-invoering in één keer"], 1,
   "Verandering loopt langs ratio en gevoel. De twee succesfactoren: betrek de mensen die het moeten doen, en zorg voor zichtbare betrokkenheid van het management.")
mc("pp3-m02", W, P, "Wie is volgens de les een stakeholder?",
   ["Alleen wie in het organogram boven het proces staat en erover beslist",
        "Iedereen die invloed heeft op je verbetering óf er gevolgen van ondervindt",
        "Alleen de opdrachtgever, de sponsor en de beoogde proceseigenaar",
        "Iedereen die in de RACI van het project een R of een A heeft"], 1,
   "Invloed hebben óf gevolgen ondervinden is genoeg. Let ook op het rimpeleffect: afdelingen die denken er niets mee te maken te hebben.")
mc("pp3-m03", W, P, "Welke rol heeft de lijnmanager die verantwoordelijk is voor het proces dat je verbetert?",
   ["Sponsor", "Proceseigenaar", "Uitvoerder", "Gebruiker"], 1,
   "De proceseigenaar is de lijnmanager die verantwoordelijk is voor het proces. De sponsor maakt mensen en middelen vrij en heeft mandaat.")
mc("pp3-m04", W, P, "De schoonmakers merken veel van het nieuwe rooster, maar hebben weinig invloed op de beslissing. Welke aanpak hoort volgens de belang-invloed-grid bij hen?",
   ["Nauw betrekken", "Tevreden houden", "Informeren", "Monitoren"], 2,
   "Veel belang en weinig invloed: informeren. Houd ze goed op de hoogte; vaak loont het om ze ook bij de uitvoering te betrekken.")
mc("pp3-m05", W, P, "Het hoofd van de technische dienst heeft veel invloed en wordt sterk geraakt door het nieuwe meldproces. Welke aanpak past?",
   ["Monitoren", "Informeren", "Tevreden houden", "Nauw betrekken"], 3,
   "Veel invloed en veel belang: nauw betrekken. Deze persoon kan het project maken of breken.")
mc("pp3-m06", W, P, "De facilitair coördinator heeft het huidige meldsysteem tien jaar geleden zelf bedacht en reageert afwijzend op jullie voorstel. Welke aanpak past bij deze oorzaak van weerstand?",
   ["Tijd vrijmaken", "Waardering voor het verleden", "Training en geruststelling", "Ruimte geven"], 1,
   "De oorzaak is gezichtsverlies. Laat zien dat het oude systeem destijds goed werkte en dat je erop voortbouwt.")
mc("pp3-m07", W, P, "Medewerkers horen op vrijdag via via dat ze vanaf maandag met een nieuw roostersysteem moeten werken. Welke oorzaak van weerstand roep je hiermee op, en wat had je moeten doen?",
   ["Verlies aan controle; ruimte geven", "Overvallen worden; voorbereiden", "Meer werk; tijd vrijmaken", "Gezichtsverlies; waardering voor het verleden"], 1,
   "Wie overvallen wordt, verzet zich. Bereid mensen tijdig voor.")
mc("pp3-m08", W, P, "Medewerkers vragen steeds: 'Waar gaat dit naartoe, en wat betekent het straks voor mijn functie?' Welke aanpak past bij deze weerstand?",
   ["Duidelijke visie", "Tijd vrijmaken", "Waardering voor het verleden", "Training en geruststelling"], 0,
   "Te veel onzekerheid vraagt om een duidelijke visie: waar gaan we naartoe en waarom.")
mc("pp3-m09", W, P, "Een medewerker zegt over het nieuwe meldportaal: 'Dat komt er toch nooit, dat hebben ze al drie keer gezegd.' In welke fase van Carnall zit deze medewerker?",
   ["Ontkenning", "Verdediging", "Verwerking", "Internalisatie"], 0,
   "De fasen van Carnall zijn ontkenning, verdediging, verwerking, aanpassing en internalisatie. Niet geloven dat de verandering doorgaat, is ontkenning.")
mc("pp3-m10", W, P, "Wat doe je in de stap 'coalitie' van Kotter-light?",
   ["Je laat de noodzaak voelen met cijfers over het probleem",
        "Je zoekt een zichtbare sponsor plus invloedrijke ambassadeurs",
        "Je vertelt de visie zo vaak mogelijk, in alle overleggen",
        "Je viert de eerste quick win samen met de werkvloer"], 1,
   "Coalitie: sponsor en ambassadeurs. Urgentie, communicatie en betrokkenheid zijn de andere drie stappen.")
mc("pp3-m11", W, P, "Een team geeft één goede presentatie over de verandering en vindt de communicatie daarmee klaar. Wat zeggen de notities daarover?",
   ["Dat is genoeg, als de presentatie maar duidelijk was en alle medewerkers erbij waren",
        "Communiceren is een doorlopende dialoog: vaak, consistent en in twee richtingen",
        "Communicatie is de taak van de sponsor en het management, niet van het studentteam",
        "Communicatie hoort pas bij de borging in week 5, als de oplossing vaststaat"], 1,
   "Vertel de visie vaak, consistent en in twee richtingen, en neem zorgen serieus.")
mc("pp3-m12", W, P, "Hoe verhoudt Kotter-light zich tot het oorspronkelijke model van Kotter?",
   ["Het is hetzelfde model van acht stappen, alleen met andere namen voor de stappen",
        "Het vereenvoudigt Kotters oorspronkelijke acht stappen tot vier stappen",
        "Het voegt vier extra stappen toe aan het veranderingsmodel van Carnall",
        "Het is Kotters model zonder de eerste stap, omdat urgentie al vaststaat"], 1,
   "Kotter heeft acht stappen; Kotter-light is een vereenvoudiging voor dit vak. Kotters stap 8, 'borg in de cultuur', komt in week 5 terug.")
mc("pp3-m13", W, P, "Waar staan de TBV's voor die je per activiteit vastlegt?",
   ["Tijd, budget en voorwaarden", "Taken, bevoegdheden en verantwoordelijkheden", "Toetsing, borging en verbetering", "Teams, belanghebbenden en verwachtingen"], 1,
   "Je legt per activiteit de taken, bevoegdheden en verantwoordelijkheden vast, met de RACI-methode.")
mc("pp3-m14", W, P, "Wat is volgens de notities de meest gehoorde klacht bij mislukte veranderingen?",
   ["'Het kostte te veel geld'",
    "'Het was niet duidelijk wat de leiding wilde'",
    "'Het systeem werkte niet'",
    "'Er was te weinig tijd voor training'"], 1,
   "Daarom stuur je op resultaat en leg je de rollen per activiteit vast.")
mc("pp3-m15", W, P, "In de RACI uit de les is de FM-manager bij 'KPI's monitoren en bijsturen' zowel A als R. Wat is juist?",
   ["Dat is fout: A en R mogen in een RACI nooit bij dezelfde persoon liggen",
        "Dat mag, al is uitvoeren en goedkeuren scheiden vaak beter",
        "Dat mag alleen als er voor die taak ook een tweede A wordt aangewezen",
        "Dat mag alleen tijdens de pilot, niet na de organisatiebrede invoering"], 1,
   "In de les is A/R bij die rij toegestaan. Het scheiden van R en A voorkomt wel dat iemand zijn eigen werk goedkeurt.")
mc("pp3-m16", W, P, "Welke betekenis heeft de S in RASCI?",
   ["Sponsor", "Support: ondersteunt actief", "Stakeholder", "Signed off: heeft getekend"], 1,
   "RASCI voegt Support toe; CAIRO voegt ook O toe, Out of the loop: expliciet níet betrokken. Op hoofdlijnen is RACI vaak genoeg.")
mc("pp3-m17", W, P, "Wat bedoelt de les met 'het gaat om rollen, niet om personen' in een RACI?",
   ["Je zet geen namen in de RACI, alleen afdelingen",
    "Dezelfde persoon kan per activiteit een andere rol hebben",
    "Elke persoon heeft in het hele project maar één rol",
    "Alleen managers kunnen Accountable zijn"], 1,
   "In het voorbeeld zijn de baliemedewerkers bij het inrichten Consulted en bij training en pilot Responsible.")
mc("pp3-m18", W, P, "Het team laat de baliemedewerkers het concept-stappenplan aanvullen voordat het definitief wordt. Hoe heet dit?",
   ["Catchball", "Schaduwdraaien", "Heijunka", "Tollgate"], 0,
   "Catchball: betrokkenen vullen het plan aan, zodat ze mede-eigenaar worden.")

# ---------- open ----------
op("pp3-o1", W, P, "Een team presenteert aan de medewerkers van de facilitaire dienst een rapport met cijfers waaruit blijkt dat het meldproces beter moet. Na een maand werkt niemand anders. Verklaar dit met de les over ratio en gevoel, en geef twee dingen die het team anders had moeten doen.",
   "Volgens Kotter loopt verandering langs ratio (feiten, cijfers) en gevoel (vertrouwen, betrokkenheid, motivatie). Cijfers brengen de noodzaak in beeld, maar motiveren zelden tot nieuw gedrag. Anders doen: de mensen betrekken die het moeten doen (bijvoorbeeld meedenken over de nieuwe werkwijze, catchball), zorgen voor zichtbare betrokkenheid van het management (sponsor), en urgentie laten voelen met hun eigen voorbeelden en quick wins vieren.",
   ["Ratio en gevoel juist uitgelegd", "Verklaring: cijfers alleen brengen mensen niet in beweging", "Twee concrete verbeteringen, gekoppeld aan de succesfactoren of Kotter-light"])
op("pp3-o2", W, P, "Voor een nieuw reserveringssysteem voor vergaderzalen zijn deze stakeholders betrokken: de directeur (beslist over budget, merkt er weinig van), het zaalteam (moet anders werken, weinig zeggenschap), de afdeling ICT (moet het systeem koppelen, kan het project vertragen) en bezoekers van buiten (merken alleen het resultaat). Plaats ze in de belang-invloed-grid en geef per stakeholder de aanpak.",
   "Directeur: veel invloed, weinig belang: tevreden houden. Zaalteam: veel belang, weinig invloed: informeren (en bij de uitvoering betrekken). ICT: veel invloed en, omdat ze het moeten koppelen, veel belang: nauw betrekken (vooraf raadplegen). Bezoekers: weinig invloed, beperkt belang: monitoren. Andere indelingen zijn goed als ze worden onderbouwd.",
   ["Directeur juist geplaatst met aanpak", "Zaalteam juist geplaatst met aanpak", "ICT juist geplaatst met aanpak", "Bezoekers geplaatst met aanpak"])
op("pp3-o3", W, P, "Leg de 20-60-20-verdeling uit. Wat betekent die voor de manier waarop je je energie verdeelt bij een verandering?",
   "Bij elke verandering zijn er grofweg 20% voorstanders, 60% onbesliste middenmoot en 20% tegenstanders. De middengroep kiest de kant van de sterkste groep. Daarom stop je je energie niet vooral in het overtuigen van tegenstanders, maar laat je de voorstanders zichtbaar succes boeken met een quick win. Dan kiest de middengroep jouw kant.",
   ["De drie groepen juist genoemd", "De middengroep kiest de kant van de sterkste groep", "Strategie: voorstanders met quick win zichtbaar maken, niet alles op tegenstanders"])
op("pp3-o4", W, P, "Werk Kotter-light in vier stappen uit voor de invoering van afvalscheiding op alle verdiepingen van een kantoor.",
   "Urgentie: laat met eigen cijfers zien hoeveel restafval er is en wat het kost, of dat de organisatie haar duurzaamheidsdoel niet haalt. Coalitie: de facilitair manager als zichtbare sponsor plus per verdieping een ambassadeur. Communicatie: vaak, consistent en in twee richtingen, bijvoorbeeld een korte uitleg in teamoverleggen en een plek voor vragen en zorgen. Betrokkenheid: medewerkers kiezen mee waar de afvalstations komen en de eerste resultaten (bijvoorbeeld 30% minder restafval na een maand) worden zichtbaar gevierd.",
   ["Urgentie met eigen cijfers", "Coalitie met sponsor en ambassadeurs", "Communicatie als doorlopende dialoog", "Betrokkenheid: rol geven en quick wins vieren"])
op("pp3-o5", W, P, "Leg het verschil uit tussen Consulted en Informed in een RACI. Wat gaat er mis als je ze verwart, in beide richtingen?",
   "Consulted: wordt vooraf om advies gevraagd, tweerichtingsverkeer. Informed: wordt achteraf op de hoogte gebracht, eenrichtingsverkeer. Maak je te veel mensen Consulted, dan krijg je onnodige vertraging. Maak je iemand Informed die Consulted had moeten zijn, dan voelt die persoon zich gepasseerd en mis je belangrijke input. Volgens de docent is dit in de praktijk het belangrijkste onderscheid.",
   ["Consulted juist uitgelegd", "Informed juist uitgelegd", "Gevolg te veel Consulted: vertraging", "Gevolg te weinig Consulted: gepasseerd voelen"])
op("pp3-o6", W, P, "Noem vier oorzaken van weerstand uit de les, met bij elke oorzaak de passende aanpak.",
   "Verlies aan controle: ruimte geven. Te veel onzekerheid: duidelijke visie. Overvallen worden: voorbereiden. Twijfel of je het kunt: training en geruststelling. Het kost eerst meer werk: tijd vrijmaken. Gezichtsverlies: waardering voor het verleden. Weerstand is geen onwil maar een voorspelbare reactie.",
   ["Eerste paar oorzaak en aanpak juist", "Tweede paar juist", "Derde paar juist", "Vierde paar juist"])

# ---------- casus ----------
cs("pp3-c1", W, P, "Clean desk bij de gemeente Lindehoven",
   "De gemeente Lindehoven (fictief) wil overstappen op flexwerken met een clean-desk-beleid, om een verdieping te kunnen afstoten. De facilitair manager is enthousiast en wil het trekken. Teamleiders van Burgerzaken vinden dat hun mensen 'een vaste plek nodig hebben om goed te kunnen werken'. Medewerkers van Burgerzaken werken er gemiddeld vijftien jaar en hebben hun bureau ingericht met foto's en planten. ICT moet een reserveringsapp koppelen aan het netwerk. De wethouder heeft het besluit genomen, maar is verder niet betrokken. Het projectteam wil de app volgende maand in één keer invoeren.",
   [("Geef voor vier stakeholders hun rol (sponsor, proceseigenaar, uitvoerder of gebruiker) of hun plaats in de belang-invloed-grid, met de aanpak.",
     "Facilitair manager: sponsor of proceseigenaar, veel invloed en veel belang: nauw betrekken. Teamleiders Burgerzaken: veel invloed op hun mensen en veel belang: nauw betrekken. Medewerkers Burgerzaken: gebruikers, veel belang en weinig invloed: informeren en betrekken bij de inrichting. ICT: uitvoerder van de koppeling, vooraf raadplegen. Wethouder: veel invloed, weinig belang in de uitvoering: tevreden houden.",
     ["Twee stakeholders juist met aanpak", "Nog twee stakeholders juist met aanpak", "Aanpak logisch gekoppeld aan de grid"]),
    ("Benoem bij de medewerkers van Burgerzaken twee oorzaken van weerstand en de passende aanpak.",
     "Verlies aan controle (geen eigen plek, foto's en planten weg): ruimte geven, bijvoorbeeld meebeslissen over teamzones of persoonlijke lockers. Te veel onzekerheid (werkt dit wel voor ons werk?): duidelijke visie, wat er verandert en waarom. Overvallen worden (invoering volgende maand in één keer): voorbereiden. Gezichtsverlies of twijfel kunnen ook, mits onderbouwd.",
     ["Eerste oorzaak met aanpak, gekoppeld aan de casus", "Tweede oorzaak met aanpak, gekoppeld aan de casus"]),
    ("Geef twee Kotter-light-acties die het team nu moet nemen, en een kritische kanttekening bij het invoeren 'in één keer'.",
     "Urgentie: met cijfers laten zien hoeveel werkplekken leeg staan en wat de verdieping kost. Coalitie: de facilitair manager zichtbaar als sponsor, met één teamleider van Burgerzaken als ambassadeur. Betrokkenheid: eerst met één team proberen en het succes zichtbaar maken. Kanttekening: invoeren in één keer vergroot het risico op weerstand en overvallen worden; een pilot met één afdeling geeft de 20% voorstanders de kans om zichtbaar succes te boeken.",
     ["Twee Kotter-light-acties concreet", "Kritische kanttekening bij de invoering in één keer"])])
cs("pp3-c2", W, P, "Een RACI met fouten",
   "Een studententeam maakt een RACI voor de invoering van een nieuw schoonmaakrooster bij een hogeschool. Rollen: facilitair manager (FM), studententeam (ST), teamleider schoonmaak (TL), schoonmaakbedrijf (SB), docenten (DO). Rij 1, rooster opstellen: FM = A, ST = R, TL = A, SB = I, DO = I. Rij 2, schoonmakers instrueren: FM = I, ST = C, TL = C, SB = C, DO = I. Rij 3, contract met het schoonmaakbedrijf aanpassen: FM = A/R, ST = I, TL = I, SB = I, DO = –.",
   [("Welke fouten zie je in rij 1 en rij 2? Leg uit waarom het fouten zijn.",
     "Rij 1 heeft twee A's (FM en TL): met twee A's geeft niemand de doorslag; er moet precies één A zijn. Rij 2 heeft geen A en geen R: niemand voert het uit en niemand is eindverantwoordelijk, dus het gebeurt waarschijnlijk niet. Controle per rij: precies één A en minstens één R.",
     ["Rij 1: twee A's als fout met uitleg", "Rij 2: geen A en geen R als fout", "Controleregel: één A, minstens één R"]),
    ("Bij rij 3 staat het schoonmaakbedrijf op Informed. Is dat verstandig? Geef een verbeterde rij 3 en licht toe.",
     "Niet verstandig: het schoonmaakbedrijf is de contractpartij en moet vooraf worden geraadpleegd (Consulted), anders voelt het zich gepasseerd en sluit het contract niet aan op wat uitvoerbaar is. Verbeterd: FM = A, ST = C of I, TL = C, SB = C (of R bij het uitwerken van het aangepaste contract), DO = –. FM mag A én R zijn, maar het scheiden van uitvoeren en goedkeuren is vaak beter.",
     ["SB moet Consulted zijn, met uitleg over gepasseerd voelen of input", "Verbeterde rij met precies één A en minstens één R"]),
    ("Herstel rij 2 en leg uit welke rol de teamleider schoonmaak daar volgens jou moet hebben.",
     "Bijvoorbeeld: FM = A, TL = R (geeft de instructie aan de eigen mensen), ST = R of C (maakt de instructiekaart), SB = C, DO = I. De teamleider is de logische uitvoerder, omdat die de schoonmakers dagelijks aanstuurt; zo wordt de nieuwe werkwijze ook eerder van de organisatie zelf.",
     ["Rij 2 hersteld met één A en minstens één R", "Onderbouwde rol voor de teamleider"])])
cs("pp3-c3", W, P, "Tablets voor housekeeping in Hotel De Waalkade",
   "Hotel De Waalkade (fictief) wil dat de 30 roomattendants hun kamerstatus voortaan op een tablet bijhouden in plaats van op papier. Ongeveer zes attendants zijn enthousiast, zes zijn uitgesproken tegen en de rest twijfelt. De tegenstanders zeggen vooral dat ze 'niet met zo'n ding overweg kunnen' en dat 'het invullen meer tijd kost dan het oplevert'. De hotelmanager wil 'eerst de tegenstanders overtuigen, dan komt de rest vanzelf'.",
   [("Reageer met de 20-60-20-verdeling op het plan van de hotelmanager.",
     "Ongeveer 20% is voor, 60% twijfelt en 20% is tegen. De middengroep kiest de kant van de sterkste groep. Beter is de voorstanders als eersten te laten werken met de tablet en hun succes zichtbaar te maken (quick win), bijvoorbeeld snellere vrijgave van kamers aan de receptie. Dan kiest de middengroep die kant. Al je energie in de tegenstanders stoppen, levert weinig op.",
     ["20-60-20 juist toegepast op de 30 attendants", "Middengroep volgt de sterkste groep", "Advies: voorstanders met quick win zichtbaar maken"]),
    ("Benoem de twee oorzaken van weerstand bij de tegenstanders en geef per oorzaak een concrete aanpak.",
     "'Niet met zo'n ding overweg kunnen': twijfel aan het eigen kunnen; aanpak training en geruststelling, bijvoorbeeld een collega-ambassadeur die naast hen de eerste dagen meeloopt. 'Kost meer tijd': het kost eerst meer werk; aanpak tijd vrijmaken, bijvoorbeeld in de eerste twee weken minder kamers per dienst plannen en het invullen zo simpel mogelijk maken.",
     ["Twijfel aan kunnen met training en geruststelling", "Meer werk met tijd vrijmaken", "Concrete acties voor het hotel"])])
